def solve():
    n = int(input())
    s = [input() for _ in range(n)]]

    g = defaultdict(list)
    for i in range(n):
        for j in range(i+1,n)):
            if s[i] in s[j]:
                g[s[i]].append(s[j])

    def dfs(node):
        visited.add(node)
        for nei in g[node]:
            if nei not in visited:
                dfs(nei)

    visited = set()
    for node in s:
        if node not in visited:
            dfs(node)

    return len(visited) == len(s)

