import math
def is_prime(n):
    if n == 2 or n == 3:
        return True
    if n < 2 or n % 2 == 0:
        return False
    d = int(math.sqrt(n)))
    for i in range(3, d+1, 2)):
        if n % i == 0:
            return False
    return True


def get_primes(n):
    primes = []
    for i in range(2, n+1)):
        if is_prime(i):
            primes.append(i)
    return primes


def solve():
    n = int(input())
    arr = list(map(int, input().split())))
    primes = get_primes(max(arr)))
    # print(primes)
    ans = []
    for i in range(len(arr))):
        if arr[i] in primes:
            ans.append(arr[i])
        else:
            div = arr[i]
            while div > 1 and arr[i] % div != 0:
                div -= 1
            ans.append(div)
    print(*ans)


solve()
